<script setup lang="ts">
import{ref,onMounted,nextTick}from'vue';type Base={id:number;name:string};type Citation={versionId:number;vectorId:string;title:string;versionNo:string;pageNumber:number|null;quote:string};type Message={id?:number;role:'user'|'assistant';content:string;citations?:Citation[];confidence?:string;sufficiency?:string;feedback?:string;error?:boolean};
const bases=ref<Base[]>([]),conversations=ref<any[]>([]),kbId=ref(0),question=ref(''),messages=ref<Message[]>([]),sending=ref(false),conversationId=ref<number|null>(null),cap=ref({embeddingConfigured:false,chatConfigured:false,chatModel:'deepseek-chat'}),scroll=ref<HTMLElement|null>(null);
async function jsonApi(path:string,options:RequestInit={}){const r=await fetch('/api'+path,{...options,headers:{Authorization:'Bearer '+sessionStorage.getItem('ops-token'),'Content-Type':'application/json',...options.headers}}),b=await r.json();if(!r.ok)throw Error(b.message);return b.data}async function loadConversations(){conversations.value=await jsonApi('/assistant/conversations')}function sample(q:string){question.value=q}function newConversation(){conversationId.value=null;messages.value=[]}
async function openConversation(id:number){const d=await jsonApi('/assistant/conversations/'+id);conversationId.value=id;messages.value=d.messages.map((m:any)=>({id:m.ID,role:m.ROLE.toLowerCase(),content:m.CONTENT,confidence:m.CONFIDENCE_LEVEL,sufficiency:m.EVIDENCE_SUFFICIENCY,feedback:m.FEEDBACK,citations:(m.citations||[]).map((c:any)=>({versionId:c.VERSION_ID,vectorId:c.VECTOR_ID,title:c.TITLE,versionNo:c.VERSION_NO,pageNumber:c.PAGE_NUMBER,quote:c.QUOTE_TEXT}))}))}
async function removeConversation(id:number){if(!confirm('确认删除这段会话及引用记录？'))return;await jsonApi('/assistant/conversations/'+id,{method:'DELETE'});if(conversationId.value===id)newConversation();await loadConversations()}async function rate(m:Message,rating:'UP'|'DOWN'){if(!m.id)return;await jsonApi('/assistant/messages/'+m.id+'/feedback',{method:'PUT',body:JSON.stringify({rating})});m.feedback=rating}
async function send(){const q=question.value.trim();if(!q||sending.value||!kbId.value)return;messages.value.push({role:'user',content:q},{role:'assistant',content:''});question.value='';sending.value=true;const answer=messages.value.at(-1)!;try{const response=await fetch('/api/assistant/chat/stream',{method:'POST',headers:{Authorization:'Bearer '+sessionStorage.getItem('ops-token'),'Content-Type':'application/json'},body:JSON.stringify({conversationId:conversationId.value,kbId:kbId.value,question:q})});if(!response.ok)throw Error((await response.json()).message||'请求失败');const reader=response.body?.getReader();if(!reader)throw Error('浏览器不支持流式响应');const decoder=new TextDecoder();let buffer='';while(true){const{done,value}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const blocks=buffer.split(/\r?\n\r?\n/);buffer=blocks.pop()||'';for(const block of blocks){let event='',data='';for(const line of block.split(/\r?\n/)){if(line.startsWith('event:'))event=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim()}if(!data)continue;const p=JSON.parse(data);if(event==='delta')answer.content+=p.content;if(event==='evidence')answer.citations=p.citations;if(event==='complete'){conversationId.value=p.conversationId;answer.id=p.messageId;answer.confidence=p.confidenceLevel;answer.sufficiency=p.evidenceSufficiency}if(event==='error')throw Error(p.message)}await nextTick();if(scroll.value)scroll.value.scrollTop=scroll.value.scrollHeight;if(done)break}}catch(e){answer.error=true;answer.content=e instanceof Error?e.message:'问答服务暂不可用'}finally{sending.value=false;loadConversations().catch(()=>{})}}
onMounted(async()=>{try{[bases.value,cap.value,conversations.value]=await Promise.all([jsonApi('/knowledge-bases'),jsonApi('/assistant/capabilities'),jsonApi('/assistant/conversations')]);if(bases.value.length)kbId.value=bases.value[0].id}catch(e){messages.value=[{role:'assistant',content:e instanceof Error?e.message:'加载失败',error:true}]}});
</script>
<template><section class="assistant-page"><div class="assistant-head"><div><span class="eyebrow">EVIDENCE-BASED ASSISTANT</span><h1>知识助手</h1><p class="muted">从资料出发进行归纳、比较和风险分析，并保留实际引用。</p></div><label>知识库<select v-model="kbId"><option v-for="b in bases" :value="b.id">{{b.name}}</option></select></label></div><div v-if="!cap.embeddingConfigured||!cap.chatConfigured" class="model-note"><span class="dot"></span><div><b>模型配置尚未完成</b><p>向量模型：{{cap.embeddingConfigured?'已配置':'未配置'}}；回答模型：{{cap.chatConfigured?'已配置':'未配置'}}</p></div></div><div class="assistant-layout"><section class="conversation-panel"><button class="new-chat" @click="newConversation">＋ 新对话</button><small>最近会话</small><article v-for="c in conversations" :class="{active:conversationId===c.ID}" @click="openConversation(c.ID)"><div><b>{{c.TITLE}}</b><small>{{c.MESSAGE_COUNT}} 条消息</small></div><button class="text-btn danger" @click.stop="removeConversation(c.ID)">删除</button></article><p v-if="!conversations.length" class="muted">暂无历史会话</p></section><div class="chat-shell"><div ref="scroll" class="chat-messages"><div v-if="!messages.length" class="chat-empty"><div class="spark">✦</div><h2>从资料出发，继续分析问题</h2><p>可以查找原文、梳理步骤、比较方案并分析风险：</p><div class="suggestions"><button @click="sample('order-service 的 Redis 连接池耗尽应该按什么顺序排查？请说明判断依据和后续建议。')">分析 Redis 排障路径</button><button @click="sample('订单服务部署手册 v2.0 对连接池有什么要求？')">查看部署要求</button><button @click="sample('发布失败时有哪些处置选择？请区分文档规定和你的建议。')">推演发布失败处置</button></div></div><div v-for="m in messages" class="message" :class="[m.role,{failed:m.error}]"><div class="avatar">{{m.role==='user'?'我':'✦'}}</div><div class="bubble"><pre>{{m.content||'正在检索并生成回答…'}}</pre><div v-if="m.confidence" class="answer-meta"><span>可信等级：{{m.confidence}}</span><span>证据：{{m.sufficiency}}</span></div><div v-if="m.citations?.length" class="citations"><b>引用依据</b><article v-for="(c,n) in m.citations"><small>[{{n+1}}] {{c.title}} · {{c.versionNo}}</small><p>{{c.quote}}</p></article></div><div v-if="m.role==='assistant'&&m.id" class="feedback"><span>这个回答有帮助吗？</span><button :class="{active:m.feedback==='UP'}" @click="rate(m,'UP')">有用</button><button :class="{active:m.feedback==='DOWN'}" @click="rate(m,'DOWN')">无用</button></div></div></div></div><form class="composer" @submit.prevent="send"><textarea v-model="question" rows="1" maxlength="1000" placeholder="输入问题，也可以要求比较方案、分析原因或推演风险…" @keydown.ctrl.enter="send"/><button :disabled="sending||!question.trim()||!kbId">{{sending?'回答中…':'发送'}}</button><small>Ctrl + Enter 发送 · 企业事实引用文档，延伸分析会明确标注</small></form></div></div></section></template>
